-- Run only after uploading the Fruits private files (Nov 1). Existing products are preserved.
-- The first three sheets are free, like the other Vocabulary sections; the rest are ₹19 each.
-- Fruits is a built-in section, so it cannot have been deleted; if staff hid it, it is shown again.
update public.sections set visible = true where id = 'vocab-fruits' and not visible;
on conflict (id) do nothing;

-- the help chat's published answers name the Vocabulary topics with free sheets; only that phrase changes
update public.faq_entries
set answer = replace(answer, 'Colours, Shapes, Sizes and Animals in Vocabulary', 'Colours, Shapes, Sizes, Animals, Animal Babies, Body Parts and Fruits in Vocabulary')
where answer like '%Colours, Shapes, Sizes and Animals in Vocabulary%';
